// Expression Trees cho phép bạn phân tích, sửa đổi và thực thi code một cách linh hoạt.
// Trong Unity, nó ít được dùng trong gameplay hàng ngày nhưng lại cực kỳ mạnh mẽ cho các hệ thống nền.

using System;
using System.Linq.Expressions;
using UnityEngine;

public class ExpressionTreeExample : MonoBehaviour
{
    void Start()
    {
        // Mục tiêu: Xây dựng một biểu thức tương đương với: (num > 5) && (num < 10)

        // 1. Tạo tham số đầu vào cho biểu thức (giống như 'num => ...')
        ParameterExpression numParam = Expression.Parameter(typeof(int), "num");

        // 2. Tạo các hằng số để so sánh
        ConstantExpression five = Expression.Constant(5, typeof(int));
        ConstantExpression ten = Expression.Constant(10, typeof(int));

        // 3. Tạo các biểu thức so sánh
        // num > 5
        BinaryExpression greaterThanFive = Expression.GreaterThan(numParam, five);
        // num < 10
        BinaryExpression lessThanTen = Expression.LessThan(numParam, ten);

        // 4. Kết hợp chúng lại bằng toán tử 'AND' (&&)
        BinaryExpression andExpression = Expression.AndAlso(greaterThanFive, lessThanTen);

        // 5. Tạo Lambda Expression từ biểu thức đã xây dựng
        // Đây là một object đại diện cho code, chưa phải là code có thể thực thi
        Expression<Func<int, bool>> lambda = Expression.Lambda<Func<int, bool>>(
            andExpression,
            new ParameterExpression[] { numParam }
        );

        Debug.Log("Cấu trúc biểu thức: " + lambda.ToString());

        // 6. Biên dịch (Compile) biểu thức thành một delegate có thể thực thi
        Func<int, bool> compiledLambda = lambda.Compile();

        // 7. Thực thi với các giá trị khác nhau
        bool resultFor7 = compiledLambda(7);   // True
        bool resultFor3 = compiledLambda(3);   // False
        bool resultFor12 = compiledLambda(12); // False

        Debug.Log("Kết quả với số 7: " + resultFor7);
        Debug.Log("Kết quả với số 3: " + resultFor3);
    }
}

/*
 * STACK (Ngăn xếp):
 * - Rất nhanh, quản lý theo kiểu LIFO (Vào sau ra trước).
 * - Mỗi luồng (thread) có một Stack riêng.
 * - Lưu trữ "Value Types" (kiểu giá trị): int, float, bool, Vector3, Quaternion, và các 'struct' bạn tự định nghĩa.
 * - Khi một hàm kết thúc, bộ nhớ trên Stack cho các biến của nó sẽ được giải phóng ngay lập tức.
 * - Rất thân thiện với hiệu năng trong Unity.
 */

public struct Point { public int x, y; }

public void StackExample()
{
    // 'a' và 'p1' là value types, được tạo trực tiếp trên Stack.
    int a = 10;
    Point p1 = new Point { x = 5, y = 5 };

    // Khi gán, toàn bộ dữ liệu được sao chép.
    int b = a; 
    Point p2 = p1;

    b = 20; // Không ảnh hưởng đến 'a'.
    p2.x = 30; // Không ảnh hưởng đến 'p1'.
}

/*
 * HEAP (Đống):
 * - Chậm hơn Stack, là vùng nhớ lớn và linh hoạt.
 * - Lưu trữ "Reference Types" (kiểu tham chiếu): tất cả các 'class', string, array.
 * - Khi tạo một đối tượng bằng 'new MyClass()', bộ nhớ được cấp phát trên Heap.
 * - Biến của bạn trên Stack chỉ là một 'con trỏ' trỏ tới địa chỉ của đối tượng trên Heap.
 * - Việc giải phóng bộ nhớ trên Heap được thực hiện bởi Garbage Collector (GC), 
 *   đây là một tiến trình tốn kém có thể gây giật game (GC spike).
 */

public class Enemy { public int health; }

public void HeapExample()
{
    // 'enemy1' là một tham chiếu trên Stack, trỏ đến một đối tượng Enemy trên Heap.
    Enemy enemy1 = new Enemy { health = 100 };

    // 'enemy2' là một tham chiếu khác trên Stack, trỏ đến CÙNG một đối tượng trên Heap.
    Enemy enemy2 = enemy1;

    enemy2.health = 50; // Thay đổi dữ liệu qua 'enemy2'.
    // Vì cả hai cùng trỏ đến một đối tượng, 'enemy1.health' bây giờ cũng là 50.
}

/*
 * KẾT LUẬN CHO UNITY DEV:
 * - Ưu tiên dùng 'struct' cho các kiểu dữ liệu nhỏ, bất biến (immutable) để tránh tạo rác cho GC.
 * - Chỉ dùng 'class' cho các đối tượng phức tạp, có trạng thái, và cần được chia sẻ qua tham chiếu.
 * - Tránh việc 'new' các class trong hàm Update() bằng mọi giá!
 */

using UnityEngine;
using System.Collections.Generic;
using System.Collections; // Namespace của ArrayList

public class BoxingExample : MonoBehaviour
{
    void Start()
    {
        // --- Boxing ---
        int i = 123; // Value type trên Stack.

        // Boxing xảy ra ở đây: một object được tạo trên Heap để chứa giá trị của 'i'.
        // Thao tác này tạo ra rác (garbage).
        object o = i; 

        // --- Unboxing ---
        // Unboxing: Lấy giá trị từ object trên Heap về lại Stack.
        int j = (int)o;
    }

    // Cạm bẫy hiệu năng kinh điển trong Unity
    void Update()
    { 
        // ---- CÁCH TỆ: Dùng collection không generic (như ArrayList) ----
        // ArrayList chứa các 'object', vì vậy mỗi lần Add một value type (như int)
        // sẽ gây ra Boxing, tạo ra rác mỗi frame. RẤT TỆ!
        ArrayList arrayList = new ArrayList();
        arrayList.Add(10); // BOXING!
        int value = (int)arrayList[0]; // UNBOXING!

        // ---- CÁCH TỐT: Dùng collection generic (như List<T>) ----
        // List<int> được thiết kế để làm việc trực tiếp với kiểu 'int'.
        // Không có Boxing, không tạo rác. LUÔN DÙNG CÁCH NÀY!
        List<int> genericList = new List<int>();
        genericList.Add(10); // KHÔNG BOXING!
        int value2 = genericList[0]; // KHÔNG UNBOXING!

        // Một ví dụ khác: Dùng string.Format với value types
        // string s = string.Format("Score: {0}", 100); // Gây Boxing cho số 100
        // Cách tốt hơn: 
        string s_good = "Score: " + 100.ToString(); // ToString() không gây Boxing.
    }
}
